codeExamples.code:
-- Run periodically (e.g., nightly) to fix the small-files problem
OPTIMIZE delta.`s3://lake/curated/events`
  WHERE event_date >= current_date() - INTERVAL 7 DAYS
  ZORDER BY (user_id, event_type);

-- Remove old, unreferenced files to reclaim storage
VACUUM delta.`s3://lake/curated/events` RETAIN 168 HOURS;

-- Inspect file-level statistics used for skipping
DESCRIBE DETAIL delta.`s3://lake/curated/events`;
